def word_frequency(text: str) -> dict[str, int]:
    import string
    text = text.lower()
    text = text.translate(str.maketrans('', '', string.punctuation))
    words = text.split()
    frequency = {}
    for word in words:
        word = word.strip(string.punctuation)
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
    return frequency
